const canvas = document.querySelector("canvas");
const ctx = canvas.getContext("2d");

function fit() {
  const ratio = devicePixelRatio || 1;
  canvas.width = Math.round(innerWidth * ratio);
  canvas.height = Math.round(innerHeight * ratio);
  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
}
fit();
still.on("resize", fit);

let bands = new Array(48).fill(0);
const shown = [];
still.on("audio", (audio) => (bands = audio.bands));

function draw() {
  const { bars, gap, mirror, rounded, falloff } = still.values;
  const w = innerWidth;
  const h = innerHeight;
  const count = Math.round(bars);
  const width = Math.max(1, (w - gap * (count - 1)) / count);
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = still.theme.accent;
  for (let i = 0; i < count; i++) {
    // Each bar shows the loudest of the bands it covers.
    const from = Math.floor((i * bands.length) / count);
    const to = Math.max(from + 1, Math.floor(((i + 1) * bands.length) / count));
    let level = 0;
    for (let b = from; b < to; b++) level = Math.max(level, bands[b]);
    shown[i] = Math.max(level, (shown[i] || 0) * falloff);
    const height = Math.max(2, shown[i] * (mirror ? h / 2 : h));
    const x = i * (width + gap);
    const y = mirror ? h / 2 - height : h - height;
    const total = mirror ? height * 2 : height;
    ctx.beginPath();
    ctx.roundRect(x, y, width, total, rounded ? Math.min(width / 2, 4) : 0);
    ctx.fill();
  }
  requestAnimationFrame(draw);
}
draw();
